var n=`1213-indio-viejo`;var t=`world-1213`;var a=`NI`;var o=`central-america-caribbean`;var s=4;var r=114;var m={en:`Indio Viejo`,ua:`Індіо в'єхо`};var g={en:`Indio Viejo is a dish from Nicaragua featuring beef chuck, yellow onion, tomato, green bell pepper. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Індіо в'єхо, страва кухні країни Нікарагуа з такими основними складниками: яловича лопатка, жовта цибуля, помідор, зелений солодкий перець. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 65 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 65 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:65,i:[[`beef-chuck`,660,`g`],[`water`,1e3,`ml`],[`yellow-onion`,150,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`tomato`,350,`g`],[`green-bell-pepper`,170,`g`],[`garlic`,5,`clove`],[`canola-oil`,30,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`masa-harina`,170,`g`],[`beef-stock`,400,`ml`],[`orange-juice`,90,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`mint`,14,`g`]]}];var d={slug:n,id:t,country:`NI`,region:o,servings:4,minutes:114,title:m,text:g,steps:l};export{a as country,d as default,t as id,r as minutes,o as region,s as servings,n as slug,l as steps,g as text,m as title};